1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	export interface Scenario {
6	  customer: Customer;
7	  steps: Step[];
8	}
9	
10	export type Step = QuoteStep | ClaimStep;
11	
12	export interface QuoteStep {
13	  op: "quote";
14	  items: Item[];
15	}
16	
17	export interface Item {
18	  type: string;
19	  material?: string;
20	  enchantment?: number;
21	  cursed?: boolean;
22	}
23	
24	export interface ClaimStep {
25	  op: "claim";
26	  policy: number;
27	  incident: Incident;
28	}
29	
30	export interface Incident {
31	  cause: string;
32	  damages: Damage[];
33	}
34	
35	export interface Damage {
36	  itemType: string;
37	  amount: number;
38	}
39	
40	export type Result = { premium: number } | { payout: number; remainingCap: number };
41	
42	const PROCESSING_FEE = 5;
43	
44	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
45	
46	/** The two rates the office quotes an item from. */
47	interface ItemRates {
48	  basePremium: number;
49	  insuranceValue: number;
50	}
51	
52	/**
53	 * The insurable item types, each with the two rates the office quotes from: the
54	 * per-item base premium and the insured value the payout cap derives from. One
55	 * table so a new item type cannot be added with only half its rates.
56	 */
57	const ITEM_RATES: Record<string, ItemRates> = {
58	  sword: { basePremium: 100, insuranceValue: 1000 },
59	  amulet: { basePremium: 60, insuranceValue: 600 },
60	  staff: { basePremium: 80, insuranceValue: 800 },
61	  potion: { basePremium: 40, insuranceValue: 400 },
62	  rune: { basePremium: 25, insuranceValue: 250 },
63	  moonstone: { basePremium: 25, insuranceValue: 250 },
64	};
65	
66	/** Unknown types rate at 0 G for now; the spec calls for an error (not yet tested). */
67	const UNRATED_ITEM: ItemRates = { basePremium: 0, insuranceValue: 0 };
68	
69	const ratesFor = (type: string): ItemRates => ITEM_RATES[type] ?? UNRATED_ITEM;
70	
71	/** Premiums round in the MHPCO's favour: always up. */
72	const roundPremium = (premium: number): number => Math.ceil(premium);
73	
74	/**
75	 * Exactly this many items of one type form a "building block", priced at a flat
76	 * rate instead of per item. A larger group is NOT a block -- 4 runes pay 4x25 G.
77	 */
78	const BLOCK_SIZE = 3;
79	const BLOCK_BASE_PREMIUM = 60;
80	
81	/** How many items of each type the policy covers -- the unit the block rule applies to. */
82	const countItemsPerType = (items: Item[]): Map<string, number> =>
83	  items.reduce(
84	    (counts, item) => counts.set(item.type, (counts.get(item.type) ?? 0) + 1),
85	    new Map<string, number>(),
86	  );
87	
88	const basePremiumForType = (type: string): number => ratesFor(type).basePremium;
89	
90	const groupBasePremium = (type: string, count: number): number =>
91	  count === BLOCK_SIZE ? BLOCK_BASE_PREMIUM : count * basePremiumForType(type);
92	
93	const policyBasePremium = (items: Item[]): number =>
94	  [...countItemsPerType(items)].reduce(
95	    (total, [type, count]) => total + groupBasePremium(type, count),
96	    0,
97	  );
98	
99	/** A customer with AT LEAST this many years of business is long-standing. */
100	const LOYALTY_THRESHOLD_YEARS = 2;
101	const LOYALTY_DISCOUNT_RATE = 0.2;
102	
103	/** Every contract after the customer's first in a scenario is a follow-up. */
104	const FOLLOW_UP_DISCOUNT_RATE = 0.15;
105	
106	const CURSE_SURCHARGE_RATE = 0.5;
107	
108	/** An enchantment AT this level or above is "high" -- level 4 carries no surcharge. */
109	const HIGH_ENCHANTMENT_LEVEL = 5;
110	const HIGH_ENCHANTMENT_SURCHARGE_RATE = 0.3;
111	
112	/** Item-scoped surcharges stack additively: a cursed, highly enchanted item pays both. */
113	const itemSurchargeRate = (item: Item): number =>
114	  (item.cursed ? CURSE_SURCHARGE_RATE : 0) +
115	  ((item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL ? HIGH_ENCHANTMENT_SURCHARGE_RATE : 0);
116	
117	/** Item-scoped surcharges apply to the affected item's own base premium. */
118	const itemSurchargeTotal = (items: Item[]): number =>
119	  items.reduce(
120	    (total, item) => total + basePremiumForType(item.type) * itemSurchargeRate(item),
121	    0,
122	  );
123	
124	const isLongStanding = (customer: Customer): boolean =>
125	  customer.yearsWithMHPCO >= LOYALTY_THRESHOLD_YEARS;
126	
127	/**
128	 * Policy-scoped modifiers apply to the policy base premium, never to item
129	 * surcharges. They stack additively, like the item-scoped ones: the
130	 * first-insurance surcharge adds, the loyalty and follow-up discounts
131	 * subtract, each computed against the untouched policy base.
132	 *
133	 * Returns the modifier AMOUNT, not a multiplier on the base. Folding this into
134	 * `policyBase * (1 + rate)` is algebraically identical but NOT identical in
135	 * floating point: 100 * 1.1 is 110.00000000000001, which `roundPremium` ceils
136	 * to 111 G. Keeping base and modifier as separate addends keeps the exact
137	 * values the spec's worked examples expect.
138	 */
139	const policyModifierTotal = (
140	  policyBase: number,
141	  customer: Customer,
142	  isFollowUp: boolean,
143	): number =>
144	  policyBase * FIRST_INSURANCE_SURCHARGE_RATE -
145	  (isLongStanding(customer) ? policyBase * LOYALTY_DISCOUNT_RATE : 0) -
146	  (isFollowUp ? policyBase * FOLLOW_UP_DISCOUNT_RATE : 0);
147	
148	const quote = (items: Item[], customer: Customer, isFollowUp: boolean): Result => {
149	  const policyBase = policyBasePremium(items);
150	  return {
151	    premium: roundPremium(
152	      policyBase +
153	        policyModifierTotal(policyBase, customer, isFollowUp) +
154	        itemSurchargeTotal(items) +
155	        PROCESSING_FEE,
156	    ),
157	  };
158	};
159	
160	/**
161	 * A quote is a follow-up contract if any contract preceded it in the scenario.
162	 * Counting the quote steps that precede a step -- rather than reading the step
163	 * index -- keeps the rule correct once claims become steps too, since a claim
164	 * is not a contract and must not make the next quote a follow-up.
165	 */
166	const isFollowUpContract = (precedingSteps: Step[]): boolean =>
167	  precedingSteps.some((step) => step.op === "quote");
168	
169	const DEDUCTIBLE_PER_DAMAGE = 100;
170	const CAP_MULTIPLE_OF_INSURANCE_SUM = 2;
171	
172	const insuranceSum = (items: Item[]): number =>
173	  items.reduce((sum, item) => sum + ratesFor(item.type).insuranceValue, 0);
174	
175	/** A policy remembers the items it covers and how much of its cap is available. */
176	interface Policy {
177	  items: Item[];
178	  remainingCap: number;
179	}
180	
181	/**
182	 * A claim names its policy by the index of the quote step that created it, so
183	 * the office keeps quoted policies under that same index.
184	 */
185	type PolicyRegister = Map<number, Policy>;
186	
187	const openPolicy = (register: PolicyRegister, quoteStepIndex: number, items: Item[]): void => {
188	  register.set(quoteStepIndex, {
189	    items,
190	    remainingCap: insuranceSum(items) * CAP_MULTIPLE_OF_INSURANCE_SUM,
191	  });
192	};
193	
194	const policyFor = (register: PolicyRegister, step: ClaimStep): Policy => {
195	  const policy = register.get(step.policy);
196	  if (!policy) throw new Error(`No policy created by step ${step.policy}`);
197	  return policy;
198	};
199	
200	/** Payouts round in the MHPCO's favour: always down. */
201	const roundPayout = (payout: number): number => Math.floor(payout);
202	
203	/** Damage to an item this enchanted is only half reimbursed. */
204	const HALF_REIMBURSEMENT_LEVEL = 8;
205	const HALF_REIMBURSEMENT_RATE = 0.5;
206	const FULL_REIMBURSEMENT_RATE = 1;
207	
208	/** How much of a damage the policy reimburses, before the deductible. */
209	const reimbursementRate = (item: Item): number =>
210	  (item.enchantment ?? 0) >= HALF_REIMBURSEMENT_LEVEL
211	    ? HALF_REIMBURSEMENT_RATE
212	    : FULL_REIMBURSEMENT_RATE;
213	
214	/**
215	 * The insured item a damage entry refers to. The spec calls for an error when a
216	 * claim names an item the policy does not cover (not yet tested); until then an
217	 * unmatched entry rates as an unenchanted item of its own type.
218	 */
219	const resolveInsuredItem = (items: Item[], damage: Damage): Item =>
220	  items.find((item) => item.type === damage.itemType) ?? { type: damage.itemType };
221	
222	/**
223	 * What one damage entry earns: the insured item it hit sets the reimbursement
224	 * rate, and each entry carries its own deductible. Never pays out negative.
225	 */
226	const reimbursementForDamage = (damage: Damage, insuredItem: Item): number =>
227	  Math.max(damage.amount * reimbursementRate(insuredItem) - DEDUCTIBLE_PER_DAMAGE, 0);
228	
229	/** What an incident claims against a policy: every damage entry it lists, summed. */
230	const claimedAmount = (incident: Incident, policy: Policy): number =>
231	  incident.damages.reduce(
232	    (total, damage) =>
233	      total + reimbursementForDamage(damage, resolveInsuredItem(policy.items, damage)),
234	    0,
235	  );
236	
237	/**
238	 * Draws a payout from the policy, which may exhaust but never overdraw the cap.
239	 * The draw is the single point where a policy's remaining cap changes.
240	 */
241	const drawFromCap = (policy: Policy, claimed: number): Result => {
242	  const payout = roundPayout(Math.min(claimed, policy.remainingCap));
243	  policy.remainingCap -= payout;
244	  return { payout, remainingCap: policy.remainingCap };
245	};
246	
247	/** Pays what the incident earns, up to whatever the policy's cap still allows. */
248	const claim = (incident: Incident, policy: Policy): Result =>
249	  drawFromCap(policy, claimedAmount(incident, policy));
250	
251	/** Every step produces exactly one result: a quote opens a policy, a claim draws on one. */
252	export const runScenario = (scenario: Scenario): { results: Result[] } => {
253	  const policies: PolicyRegister = new Map();
254	
255	  const runStep = (step: Step, stepIndex: number): Result => {
256	    if (step.op === "claim") return claim(step.incident, policyFor(policies, step));
257	    openPolicy(policies, stepIndex, step.items);
258	    return quote(
259	      step.items,
260	      scenario.customer,
261	      isFollowUpContract(scenario.steps.slice(0, stepIndex)),
262	    );
263	  };
264	
265	  return { results: scenario.steps.map(runStep) };
266	};
